using import String
using import Array
using import Map
using import struct
using import IO
using import C.stdlib
using import C.stdio
using import C.time

struct Transition
    target : u32
    count : u32
    probability : f32

struct Node
    id : u32
    transitions : Array Transition

struct Model
    symbols : Map String u32
    inverse_symbols : Array String
    nodes : Array Node

fn create-model ()
    local m : Model
    m

fn read-file-content (path)
    let f = (fopen path "rb")
    if (null? f)
        return (String "")

    fseek f 0 SEEK_END
    let size = (ftell f)
    fseek f 0 SEEK_SET

    let buffer = (malloc (+ size 1))
    fread buffer 1 (resultof size) f
    fclose f

    let data = (String (cast buffer (& i8)) (resultof size))
    free buffer
    data

fn get-symbol-id (model token)
    if (model.symbols @ token)
        return (unwrap (model.symbols @ token))

    let id = (countof model.inverse_symbols)
    let token-copy = (String token)
    'set model.symbols token-copy id
    'append model.inverse_symbols token-copy

    local node : Node
    node.id = id
    'append model.nodes node

    id

fn tokenize (text)
    let len = (countof text)
    local tokens : Array String
    local start = 0
    local i = 0

    while (< i len)
        let c = (ptr-at text i)
        if (or (== c 32) (== c 10) (== c 13) (== c 9))
            if (> i start)
                let sub = (slice text start i)
                'append tokens (String sub)
            set start = (+ i 1)
        set i (+ i 1)

    if (> i start)
        let sub = (slice text start i)
        'append tokens (String sub)

    tokens

fn train-model (model text)
    let tokens = (tokenize text)
    let token-count = (countof tokens)

    if (== token-count 0)
        return model

    local prev-id = (get-symbol-id model (tokens @ 0))

    for i in (range 1 token-count)
        let token = (tokens @ i)
        let curr-id = (get-symbol-id model token)
        let node-ptr = ('at model.nodes prev-id)

        local found = false
        for j in (range 0 (countof node-ptr.transitions))
            let trans-ptr = ('at node-ptr.transitions j)
            if (== trans-ptr.target curr-id)
                set trans-ptr.count (+ trans-ptr.count 1)
                set found = true
                break

        if (not found)
            local t : Transition
            t.target = curr-id
            t.count = 1
            t.probability = 0.0
            'append node-ptr.transitions t

        set prev-id = curr-id

fn normalize-model (model)
    for i in (range 0 (countof model.nodes))
        let node = ('at model.nodes i)
        local total = 0

        for j in (range 0 (countof node.transitions))
            let t = ('at node.transitions j)
            set total (+ total t.count)

        local new-transitions : Array Transition

        for j in (range 0 (countof node.transitions))
            let t = ('at node.transitions j)
            set t.probability (/ (cast t.count f32) (cast total f32))
            if (> t.probability 0.001)
                'append new-transitions t

        set node.transitions new-transitions

fn serialize-model (model path)
    let f = (fopen path "wb")
    if (null? f)
        return false

    let count = (countof model.inverse_symbols)
    fwrite (& count) 4 1 f

    for i in (range 0 count)
        let s = (model.inverse_symbols @ i)
        let len = (countof s)
        fwrite (& len) 4 1 f
        fwrite s len 1 f

    for i in (range 0 count)
        let node = (model.nodes @ i)
        let t-count = (countof node.transitions)
        fwrite (& t-count) 4 1 f

        for j in (range 0 t-count)
            let t = (node.transitions @ j)
            fwrite (& t.target) 4 1 f
            fwrite (& t.probability) 4 1 f

    fclose f
    true

fn deserialize-model (path)
    local model : Model
    m = (create-model)

    let f = (fopen path "rb")
    if (null? f)
        return model

    local count : u32
    fread (& count) 4 1 f

    for i in (range 0 count)
        local len : u32
        fread (& len) 4 1 f
        let buffer = (malloc (+ len 1))
        fread buffer 1 len f
        let s = (String (cast buffer (& i8)) len)

        'append model.inverse_symbols s
        'set model.symbols s i

        local node : Node
        node.id = i
        'append model.nodes node
        free buffer

    for i in (range 0 count)
        local t-count : u32
        fread (& t-count) 4 1 f
        let node = ('at model.nodes i)

        for j in (range 0 t-count)
            local t : Transition
            fread (& t.target) 4 1 f
            fread (& t.probability) 4 1 f
            t.count = 0
            'append node.transitions t

    fclose f
    model

fn pick-next (model current-id)
    if (>= current-id (countof model.nodes))
        return -1:i32

    let node = (model.nodes @ current-id)
    if (== (countof node.transitions) 0)
        return -1:i32

    let r = (/ (cast (rand) f32) (cast RAND_MAX f32))
    local accum = 0.0

    for i in (range 0 (countof node.transitions))
        let t = (node.transitions @ i)
        set accum (+ accum t.probability)
        if (<= r accum)
            return (cast t.target i32)

    let last = (node.transitions @ (- (countof node.transitions) 1))
    cast last.target i32

fn generate-text (model start-text max-len)
    let tokens = (tokenize start-text)
    if (== (countof tokens) 0)
        return (String "")

    local output : String
    output = (String start-text)

    let last-token = (tokens @ (- (countof tokens) 1))
    if (not (model.symbols @ last-token))
        return output

    local current-id = (unwrap (model.symbols @ last-token))

    for i in (range 0 max-len)
        let next-id = (pick-next model current-id)
        if (== next-id -1)
            break

        let next-token = (model.inverse_symbols @ next-id)
        let space = (String " ")
        set output (.. output space next-token)
        set current-id (cast next-id u32)

    output

fn main (argc argv)
    srand (cast (time null) u32)

    if (< argc 2)
        print "Usage: main <train|chat> [file]"
        return 0

    let mode = (String (argv @ 1))

    if (== mode "train")
        if (< argc 3)
            print "Please provide text file."
            return 1

        let filepath = (argv @ 2)
        print "Reading corpus..."
        let text = (read-file-content filepath)

        print "Training model..."
        local model = (create-model)
        train-model model text

        print "Normalizing probabilities..."
        normalize-model model

        print "Saving brain..."
        serialize-model model "brain.bin"
        print "Done."

    elseif (== mode "chat")
        print "Loading brain..."
        let model = (deserialize-model "brain.bin")
        print "Brain loaded. Type a starting word:"

        local buffer : (array i8 256)
        while true
            printf "> "
            let input = (fgets &buffer 256 stdin)
            if (== input null)
                break

            let s-input = (String input)
            let trimmed = (tokenize s-input) 

            if (> (countof trimmed) 0)
                let seed = (trimmed @ 0)
                let result = (generate-text model seed 50)
                print result
            else
                print "Please enter a valid word."

    else
        print "Unknown mode."

    0

